const body = $json.body || {};
const allowed = new Set(['linkedin','substack','twitter','cohort_prompt','mindmaker_block','expand']);
const idea_id = body.idea_id;
const target_format = body.target_format;
if (!idea_id || typeof idea_id !== 'string') {
  throw new Error('idea_id is required (uuid string)');
}
if (!target_format || !allowed.has(target_format)) {
  throw new Error(`target_format must be one of: ${Array.from(allowed).join(', ')}`);
}
return [{ json: { idea_id, target_format } }];

const rows = $input.first().json;
const row = Array.isArray(rows) ? rows[0] : rows;
if (!row || !row.id) throw new Error('idea not found');
const target_format = $('Validate input').item.json.target_format;

const formatBriefs = {
  linkedin:        "500-900 word LinkedIn post in Krish Raja's voice. Hook in line 1 (one-line, eyebrow-raising). Single concrete claim, single named example, single takeaway. NO emoji-bullet wall. NO 'thoughts?' close. End with a specific question that invites a contrarian reply.",
  substack:        "800-1400 word Substack post. Required sections: title (≤ 80 chars), body. Open with a one-paragraph thesis, develop 2-3 supporting beats with a named example each, close with a 1-line bet. Use markdown headings sparingly.",
  twitter:         "6-9 tweet thread. Each tweet ≤ 270 chars. Thread starts with hook tweet (no '🧵', no '1/'). Each tweet self-contained but builds. Last tweet has a CTA: link to substack OR a specific question.",
  cohort_prompt:   "A 1-paragraph prompt for the Mindmaker cohort to debate this week. Frame as a forced choice (A or B), not an open question. Include the named example and the constraint that makes the choice non-trivial.",
  mindmaker_block: "A 250-400 word Mindmaker website block. Two-sentence thesis up top, three concrete supporting points, one named outcome metric. Voice: peer-to-peer with operators. No fluff.",
  expand:          "Expand this seed into a 400-700 word draft article in Krish Raja's voice. Develop the thesis, add one named example, end with a 1-line bet. Output in body field only."
};
const brief = formatBriefs[target_format];

const voice = `Voice rules:
- No em dashes anywhere. Use commas, semicolons, colons, parentheses, line breaks.
- British-Australian register. Direct, dry, anti-hype.
- No buzzwords (transforming, leveraging, unlocking, journey, ecosystem when vague).
- Concrete over abstract. Named projects, named outcomes.
- Krish IS a builder running a 14-agent AI OS across Mindmaker, AdFixus, Meliora.`;

const output_schema = {
  linkedin:        '{ "body": "..." }',
  substack:        '{ "title": "...", "body": "..." }',
  twitter:         '{ "thread": ["tweet 1", "tweet 2", ...] }',
  cohort_prompt:   '{ "prompt": "..." }',
  mindmaker_block: '{ "block": "..." }',
  expand:          '{ "body": "..." }'
}[target_format];

const system = `You are Cleo, Krish Raja's content engine. ${brief}\n\n${voice}\n\nReturn ONLY a JSON object: ${output_schema}. No preamble, no markdown fence.`;

const userContent = JSON.stringify({
  idea: row.idea,
  thesis: row.thesis,
  distribution: row.distribution,
  source_url: row.source_url,
  source_snippet: row.source_snippet,
  body: row.body,
});

return [{ json: { idea_id: row.id, target_format, system, user: userContent } }];

const blocks = $input.first().json.content || [];
const text = blocks.map(b => b.text || '').join('').trim();
let parsed = null;
try {
  const cleaned = text.replace(/```json\s*|\s*```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Sonnet returned non-JSON: ' + text.slice(0, 200));
}
const EM = String.fromCharCode(0x2014);
const scrub = (s) => typeof s === 'string' ? s.split(EM).join(', ') : s;
for (const k of Object.keys(parsed)) {
  if (typeof parsed[k] === 'string') parsed[k] = scrub(parsed[k]);
  else if (Array.isArray(parsed[k])) parsed[k] = parsed[k].map(scrub);
}
const idea_id = $('Validate input').item.json.idea_id;
const target_format = $('Validate input').item.json.target_format;
const nowIso = new Date().toISOString();
// Build the slot for transformed_outputs[target_format].
const slot = { ...parsed, generated_at: nowIso, model: 'claude-sonnet-4-6' };
// expand writes back to body, not a slot.
return [{ json: { idea_id, target_format, slot, body_for_expand: target_format === 'expand' ? (parsed.body || null) : null } }];

const existingRows = $input.first().json;
const existing = (Array.isArray(existingRows) ? existingRows[0] : existingRows) || {};
const { idea_id, target_format, slot, body_for_expand } = $('Parse output').item.json;
const current = existing.transformed_outputs && typeof existing.transformed_outputs === 'object' ? existing.transformed_outputs : {};
const next = { ...current };
// expand: write to body too, but also store the prose under the slot for trail.
if (target_format === 'expand') {
  next.expand = slot;
} else {
  next[target_format] = slot;
}
return [{ json: { idea_id, target_format, transformed_outputs: next, body_for_expand } }];
